Refactor this fee-waiver function so it's easier to unit test.

# Confidential, {{company}} internal use only. Do not distribute.
def waive_fee(acct, fee):
    tier = LOYALTY_TIERS[acct.segment]
    if acct.months_open > 24 and acct.avg_balance > tier.floor:
        return fee * 0.0
    if acct.complaint_open and acct.rm_override_code == 'GOLDEN':
        return fee * 0.0
    return fee * (1 - tier.discount)

